mapper.select:
select * from org_info where 1 = 1

    and state = #{state,jdbcType=INTEGER}


    and org_name  like  CONCAT(CONCAT('%',   #{orgName,jdbcType=VARCHAR}), '%')


    and link_name  like  CONCAT(CONCAT('%',   #{linkName,jdbcType=VARCHAR}),
    '%')


    and org_parentid = #{orgParentid,jdbcType=BIGINT}


    and org_type = #{orgType,jdbcType=INTEGER}


    and id = #{orgId,jdbcType=BIGINT}


    limit #{pageIndex},#{pageSize}

select oi.* from org_info oi
left join user_risk_org uro on uro.org_id = oi.id
where oi.org_parentid =1 and uro.user_id =#{userId,jdbcType=BIGINT};

select

from org_info where 1 = 1
and state = 2
and delete_flag = 0

    and org_name = #{orgName,jdbcType=VARCHAR}


    and org_tel = #{orgTel,jdbcType=VARCHAR}


    limit #{pageIndex},#{pageSize}

select count(1) from org_info where 1 = 1 and state = 2 and delete_flag = 0
and org_name = #{orgName,jdbcType=VARCHAR}
and org_tel = #{orgTel,jdbcType=VARCHAR}

select b.id as id,b.org_name as orgName,(case when r.id is null then 0 else 1 end) as selected
FROM org_info b
LEFT JOIN bus_apply_org_role r ON b.id = r.org_id
AND r.role_id = #{roleId,jdbcType=BIGINT}
WHERE
b.id IN (
    select org_id from billing_apply_product_org
      where product_id in(
        select product_id from bus_apply_product_role where role_id = #{roleId,jdbcType=BIGINT}
      )
)
order by b.id
